    parameters = {
        radius = 0.0775
        dist = 1.53
        focus_xw = 0.2
        focus_yh = 0.125
        I1 = 1e10
        T1 = 45
        Lmin = l_min
        Lmax = l_max
    }
}

component Guide {
    type = "Guide"
    parameters = {
        w1 = 0.170696
        h1 = 0.129
        w2 = 0.340522
        h2 = 0.129
        l = 1.870
        R0 = R0_para
        Qc = Qc_para
        alpha = alpha_para
        m = MGUIDE
        W = W_para
    }
