        Qcy = Qc_para
        alphax = alpha_para
        alphay = alpha_para
        W = W_para
        mx = 0
        my = MGUIDE
    }
}

component Monochromator_curved {
    type = "Monochromator_curved"
    parameters = {
        zwidth = 0.02
        yheight = 0.02
        gap = 0.0005
        NH = 15
        NV = 7
        mosaich = 40
        mosaicv = 40
        r0 = 1.0
        t0 = 0.00001
